        SELECT ?chart ?chartLabelEn ?chartLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start (COUNT(DISTINCT ?item) AS ?gold_count_estimate) WHERE {
        ?item wdt:P31 wd:Q134556 .
        ?item wdt:P577 ?date .
        BIND(YEAR(?date) AS ?year) .
        FILTER(?year >= 1950 && ?year <= 2025) .
        ?item wdt:P2291 ?chart .
        ?item wdt:P136 ?genre .
        ?chart rdfs:label ?chartLabelEn FILTER(LANG(?chartLabelEn) = "en") .
        OPTIONAL { ?chart rdfs:label ?chartLabelRu FILTER(LANG(?chartLabelRu) = "ru") . }
        ?genre rdfs:label ?genreLabelEn FILTER(LANG(?genreLabelEn) = "en") .
        OPTIONAL { ?genre rdfs:label ?genreLabelRu FILTER(LANG(?genreLabelRu) = "ru") . }
        BIND((FLOOR((?year - 1950) / 10) * 10 + 1950) AS ?period_start) .
        }
        GROUP BY ?chart ?chartLabelEn ?chartLabelRu ?genre ?genreLabelEn ?genreLabelRu ?period_start
      }
      FILTER(?gold_count_estimate >= 5 && ?gold_count_estimate <= 180)
    }
    ORDER BY DESC(?gold_count_estimate)
    LIMIT 800
